using CheckoutPricing.Application;
using CheckoutPricing.Domain;

namespace CheckoutPricing.UnitTest.Features.LoyaltyDiscount;

public class CalculateLoyaltyDiscountAcceptanceTests
{
    private static int Charged(LoyaltyTier tier, int subtotalCents) =>
        new CalculateLoyaltyDiscount()
            .Handle(new CalculateLoyaltyDiscountQuery(subtotalCents, tier))
            .TotalCents;

    [Fact]
    public void S1_BronzeCustomerIsChargedBronzePrice()
    {
        // S1 Bronze customer is charged the Bronze price
        Assert.Equal(9500, Charged(LoyaltyTier.Bronze, 10000));
    }

    [Fact]
    public void S2_SilverCustomerIsChargedSilverPrice()
    {
        // S2 Silver customer is charged the Silver price
        Assert.Equal(9000, Charged(LoyaltyTier.Silver, 10000));
    }

    [Fact]
    public void S3_GoldCustomerIsChargedGoldPrice()
    {
        // S3 Gold customer is charged the Gold price
        Assert.Equal(8500, Charged(LoyaltyTier.Gold, 10000));
    }

    [Fact]
    public void S4_BronzeReductionLandsOnWholeCentInCustomersFavour()
    {
        // S4 Bronze customer's reduction lands on a whole cent in their favour
        Assert.Equal(7, Charged(LoyaltyTier.Bronze, 7));
    }
}

